import sys
from math import pi, sin, cos, sqrt

def find_release_point(b, tx, ty):
    def spiral_eq(phi):
        return b * phi

    def derivative_spiral_eq(phi):
        return b

    def target_line_eq(phi):
        r = spiral_eq(phi)
        return (tx / r) * phi, (ty / r) * phi

    def distance_to_target(x, y):
        return sqrt((x - tx)**2 + (y - ty)**2)

    def f(phi):
        x, y = target_line_eq(phi)
        return distance_to_target(x, y) - spiral_eq(phi)

    def df(phi):
        x, y = target_line_eq(phi)
        dx_dphi = (tx / spiral_eq(phi)) * derivative_spiral_eq(phi) - (x - tx) / distance_to_target(x, y)
        dy_dphi = (ty / spiral_eq(phi)) * derivative_spiral_eq(phi) - (y - ty) / distance_to_target(x, y)
        return dx_dphi**2 + dy_dphi**2

    phi = 0
    while True:
        fx = f(phi)
        if abs(fx) < 1e-5:
            break
        dfx = df(phi)
        if dfx == 0:
            break
        phi -= fx / dfx

    x, y = target_line_eq(phi)
    return x, y

