def find_release_point(b, tx, ty):
    def f(phi):
        r = b * phi
        return (r * cos(phi), r * sin(phi))

    def df(phi):
        r = b * phi
        return (-r * sin(phi) + b * cos(phi), r * cos(phi) + b * sin(phi))

    def g(phi):
        rx, ry = f(phi)
        dx, dy = df(phi)
        txm, tym = tx - rx, ty - ry
        return txm * dy - tym * dx

    def dg(phi):
        _, dy = df(phi)
        txm, tym = tx - f(phi)[0], ty - f(phi)[1]
        return txm * dy - tym * df(phi)[1]

    phi_guess = 100
    while True:
        phi_new = phi_guess - g(phi_guess) / dg(phi_guess)
        if abs(phi_new - phi_guess) < 1e-5:
            break
        phi_guess = phi_new

    rx, ry = f(phi_guess)
    return rx, ry

