import math

def find_release_point(b, tx, ty):
    def f(phi):
        r = b * phi
        return r * math.cos(phi) - tx, r * math.sin(phi) - ty

    def df(phi):
        r = b * phi
        return b * (math.cos(phi) - r * math.sin(phi)), b * (math.sin(phi) + r * math.cos(phi))

    phi_guess = math.atan2(ty, tx)
    while True:
        fx, fy = f(phi_guess)
        J = df(phi_guess)
        delta_phi = -(fx / J[0] + fy / J[1])
        phi_guess += delta_phi
        if abs(delta_phi) < 1e-5:
            break

    r = b * phi_guess
    return r * math.cos(phi_guess), r * math.sin(phi_guess)

