import numpy as np
from scipy.optimize import fsolve

def archimedes_spiral(r, b):
    return r / b

def distance_to_spiral(phi, b, tx, ty):
    r = archimedes_spiral(phi, b)
    sx = r * np.cos(phi)
    sy = r * np.sin(phi)
    return np.sqrt((sx - tx)**2 + (sy - ty)**2)

def find_detachment_angle(b, tx, ty):
    def equation(phi):
        return distance_to_spiral(phi, b, tx, ty)

    phi_initial_guess = np.arctan2(ty, tx)
    phi_solution = fsolve(equation, phi_initial_guess)[0]
    return phi_solution

def main():
    b, tx, ty = map(float, input().split())
    phi = find_detachment_angle(b, tx, ty)
    r = archimedes_spiral(phi, b)
    sx = r * np.cos(phi)
    sy = r * np.sin(phi)
    print(f"{sx:.10f} {sy:.10f}")

if __name__ == "__main__":
    main()
